  if(action==='decide'){const result=await api('request_decide',{requestId:button.dataset.request,decision:button.dataset.decision});if(!stillHere())return;if(result.notification&&state.hub)state.notifications[state.hub.id]=result.notification;await refreshMe();if(stillHere()){notify(button.dataset.decision==='approve'?'Member approved. Access follows their original trial or confirmed membership.':'Request passed.');await render()}}
